# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer, "stale generation refusal records" do
  it "records every retried stale-generation refusal although each batch transaction rolls back" do
    company = create(:company)
    project = create(:project, client: create(:client, company: company))
    # The suite starts at generation 1, and the contract refuses a generation
    # below 1 as invalid_snapshot, so raise it before building a stale batch.
    TimekeepingOwnership.current.update!(generation: 2)
    ownership = TimekeepingOwnership.current
    expect(ownership.handoff_step).to be_nil

    entry = TimekeepingSnapshots.entry(id: 93_001, company_id: company.id, version: 1, project_id: project.id,
                                       user_id: create(:user).id)
    stale_batch = TimekeepingSnapshots.batch(
      TimekeepingSnapshots.item(entry, generation: ownership.generation - 1, outbox_position: 1)
    )

    # Section 11.3: "any `409 stale_generation` outside a handoff". The relay re-sends a
    # batch that did not get a 200, so the same stale batch arrives twice. The refusal
    # rolls the batch back; a record written inside that transaction would vanish and
    # the alert would never see either refusal.
    2.times do
      result = described_class.call(batch: stale_batch, idempotency_key: SecureRandom.uuid)
      expect([result.status, result.body.to_h.stringify_keys]).to eq([409, { "reason" => "stale_generation" }])
    end

    refusals = TimekeepingStaleGenerationRefusal.where(company_id: company.id)
    expect(refusals.count).to eq(2)
    expect(refusals.pluck(:handoff_step)).to eq([nil, nil])
    expect(TimesheetEntry.where(id: 93_001)).to be_empty
  end
end

RSpec.describe Timekeeping::ProjectionConsumer, "stale generation refusal attribution" do
  it "attributes a two-company stale batch to each company once and to no other company" do
    company_a = create(:company)
    company_b = create(:company)
    bystander = create(:company)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    TimekeepingOwnership.current.update!(generation: 2)
    stale_generation = TimekeepingOwnership.current.generation - 1

    batch = TimekeepingSnapshots.batch(
      TimekeepingSnapshots.item(
        TimekeepingSnapshots.entry(id: 93_011, company_id: company_a.id, version: 1, project_id: project_a.id,
                                   user_id: create(:user).id),
        generation: stale_generation, outbox_position: 1
      ),
      TimekeepingSnapshots.item(
        TimekeepingSnapshots.entry(id: 93_012, company_id: company_a.id, version: 1, project_id: project_a.id,
                                   user_id: create(:user).id),
        generation: stale_generation, outbox_position: 2
      ),
      TimekeepingSnapshots.item(
        TimekeepingSnapshots.entry(id: 93_013, company_id: company_b.id, version: 1, project_id: project_b.id,
                                   user_id: create(:user).id),
        generation: stale_generation, outbox_position: 3
      )
    )

    # "It logs each alert with `company_id`." A refusal counted under the wrong company,
    # or counted once per snapshot, would point the operator at the wrong tenant.
    result = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    expect(result.status).to eq(409)
    expect(TimekeepingStaleGenerationRefusal.group(:company_id).count)
      .to eq(company_a.id => 1, company_b.id => 1)
    expect(TimekeepingStaleGenerationRefusal.where(company_id: bystander.id)).to be_empty
  end
end
